import{_ as o,a0 as p,w as d,s as r,ao as n,I as t,x as s,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Linux 中實時監控日誌文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中實時監控日誌文件 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中實時監控日誌文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中實時監控日誌文件 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server]","title":"如何在 Linux 中實時監控日誌文件","tag":"202208","desc":""},"relativePath":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md","filePath":"[post].md"}'),u={name:"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md"};function g(h,i,k,b,f,m){const a=p("Link");return d(),r("div",null,[i[21]||(i[21]=n('<h1 id="如何在-linux-中實時監控日誌文件" tabindex="-1">如何在 Linux 中實時監控日誌文件 <a class="header-anchor" href="#如何在-linux-中實時監控日誌文件" aria-label="Permalink to “如何在 Linux 中實時監控日誌文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/19/194609f1njqu096uhy919i.jpg" alt=""></p><blockquote><p>本教程介紹瞭如何實時監控 Linux 日誌文件（桌面、服務器或應用）以進行診斷和故障排除。</p></blockquote><p>當你在 Linux 桌面、服務器或任何應用中遇到問題時，你首先會查看單獨的日誌文件。日誌文件通常是文本流和來自應用的帶有時間戳的消息。它可以幫助你縮小特定問題的範圍，並使你能夠找到問題的原因。它還可以幫助從網絡獲得幫助。</p><p>一般來説，所有的日誌文件都位於 <code>/var/log</code>。此目錄包含特定應用和服務的擴展名為 <code>.log</code> 的日誌文件，它還包含了其他含有日誌的獨立目錄。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/log-files-in-var-log-1024x312.jpeg" alt="log files in var-log"></p><p>所以，如果你想監控一堆日誌文件或特定的一個，這裏有一些方法可以做到。</p><h3 id="linux-實時監控日誌文件" tabindex="-1">Linux 實時監控日誌文件 <a class="header-anchor" href="#linux-實時監控日誌文件" aria-label="Permalink to “Linux 實時監控日誌文件”">​</a></h3><h4 id="使用-tail-命令" tabindex="-1">使用 tail 命令 <a class="header-anchor" href="#使用-tail-命令" aria-label="Permalink to “使用 tail 命令”">​</a></h4><p><code>tail</code> 命令是實時跟蹤日誌文件的最基本方式。特別是如果你在只有終端而沒有 GUI 的服務器中。這很有幫助。</p><p>基本語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail /path/to/log/file</span></span></code></pre></div><p>用法：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/Monitoring-multiple-log-files-via-tail.jpeg" alt="Monitoring multiple log files via tail"></p><p>可以使用開關 <code>-f</code> 跟蹤實時更新的日誌文件。例如，如果要關注 syslog，可以使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog</span></span></code></pre></div><p>你可以使用單個命令監控多個日誌文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>如果要監視 HTTP 或 sftp 或任何服務器，可以在此命令中使用它們各自的日誌文件。</p><p>請記住，上述命令需要管理員權限。</p><h4 id="使用-lnav-日誌文件瀏覽器" tabindex="-1">使用 lnav（日誌文件瀏覽器） <a class="header-anchor" href="#使用-lnav-日誌文件瀏覽器" aria-label="Permalink to “使用 lnav（日誌文件瀏覽器）”">​</a></h4><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/lnav-Running.jpeg" alt="lnav Running"></p><p><code>lnav</code> 是一個出色的程序，你可以用它來用彩色編碼的信息以更有條理的方式監控日誌文件。在 Linux 系統中，這個工具不是默認安裝的。你可以用下面的命令來安裝它：</p><p>Ubuntu：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lnav</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install lnav</span></span></code></pre></div>',27)),t("p",null,[i[1]||(i[1]=s("lnav 的好處在於，如果你不想安裝它，你可以下載其預編譯的可執行文件並在任何地方運行它，甚至可以從 U 盤上運行。無需設置，並加載了功能。使用 lnav，你可以通過 SQL 查詢日誌文件，以及其他很酷的功能，你可以在其",-1)),e(a,{href:"https://lnav.org/features"},{default:l(()=>[...i[0]||(i[0]=[s("官方網站",-1)])]),_:1}),i[2]||(i[2]=s("上學習。",-1))]),i[22]||(i[22]=n(`<p>安裝後，你可以在具有管理員權限的終端上運行 <code>lnav</code>，它會默認顯示 <code>/var/log</code> 中的所有日誌並開始實時監控。</p><h4 id="關於-systemd-的-journalctl-的一個説明" tabindex="-1">關於 systemd 的 journalctl 的一個説明 <a class="header-anchor" href="#關於-systemd-的-journalctl-的一個説明" aria-label="Permalink to “關於 systemd 的 journalctl 的一個説明”">​</a></h4><p>當今所有現代 Linux 發行版都主要使用 systemd。 systemd 提供了運行 Linux 操作系統的基本框架和組件。 systemd 通過 <code>journalctl</code> 提供日誌服務，這有助於管理來自所有 systemd 服務的日誌。你還可以使用以下命令實時監控各個 systemd 服務和日誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -f</span></span></code></pre></div><p>以下是一些特定的 <code>journalctl</code> 命令，可用於多種情況。你可以將這些與上面的 <code>-f</code> 選項結合使用以開始實時監控。</p><p>對於緊急系統消息，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -p 0</span></span></code></pre></div><p>顯示帶有解釋的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -xb -p 3</span></span></code></pre></div><p>使用時間控制過濾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --since &quot;2022-12-04 06:00:00&quot;</span></span>
<span class="line"><span>journalctl --since &quot;2022-12-03&quot; --until &quot;2022-12-05 03:00:00&quot;</span></span>
<span class="line"><span>journalctl --since yesterday</span></span>
<span class="line"><span>journalctl --since 09:00 --until &quot;1 hour ago&quot;</span></span></code></pre></div>`,11)),t("p",null,[i[4]||(i[4]=s("如果你想了解更多關於 journalctl 的詳細信息，我已經在這寫了份 ",-1)),e(a,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:l(()=>[...i[3]||(i[3]=[s("指南",-1)])]),_:1}),i[5]||(i[5]=s("。",-1))]),i[23]||(i[23]=t("h3",{id:"結束語",tabindex:"-1"},[s("結束語 "),t("a",{class:"header-anchor",href:"#結束語","aria-label":"Permalink to “結束語”"},"​")],-1)),i[24]||(i[24]=t("p",null,"我希望這些命令和技巧可以幫助你找到桌面或服務器中問題/錯誤的根本原因。有關更多詳細信息，你可以隨時參考手冊頁並使用各種選項。如果你對本文有任何意見或想法，請使用下面的評論欄告訴我。",-1)),i[25]||(i[25]=t("p",null,"乾杯。",-1)),i[26]||(i[26]=t("hr",null,null,-1)),t("p",null,[i[7]||(i[7]=s("via: ",-1)),e(a,{href:"https://www.debugpoint.com/monitor-log-files-real-time/"},{default:l(()=>[...i[6]||(i[6]=[s("https://www.debugpoint.com/monitor-log-files-real-time/",-1)])]),_:1})]),t("p",null,[i[12]||(i[12]=s("作者：",-1)),e(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...i[8]||(i[8]=[s("Arindam",-1)])]),_:1}),i[13]||(i[13]=s(" 選題：",-1)),e(a,{href:"https://github.com/lkxed"},{default:l(()=>[...i[9]||(i[9]=[s("lkxed",-1)])]),_:1}),i[14]||(i[14]=s(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:l(()=>[...i[10]||(i[10]=[s("geekpi",-1)])]),_:1}),i[15]||(i[15]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[11]||(i[11]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[18]||(i[18]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[16]||(i[16]=[s("LCTT",-1)])]),_:1}),i[19]||(i[19]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...i[17]||(i[17]=[s("Linux中國",-1)])]),_:1}),i[20]||(i[20]=s(" 榮譽推出",-1))])])}const y=o(u,[["render",g]]);export{v as __pageData,y as default};
